import{_ as t,C as l,o as i,c as s,j as a,a as r,E as n,a6 as o}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"其实，自律很容易","description":"","frontmatter":{"title":"其实，自律很容易","originalTitle":"Self-discipline is easy, actually","date":"2025-07-31","originalUrl":"https://thedankoe.com/letters/self-discipline-is-easy-actually/","minutes":8,"sourceHash":"7c81c7aabc863428991ead62ad1ff3cb617a3686f00a1210e53cadadae175b07","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/self-discipline-is-easy-actually/"}]]},"headers":[],"relativePath":"letters/self-discipline-is-easy-actually.md","filePath":"letters/self-discipline-is-easy-actually.md"}'),c={name:"letters/self-discipline-is-easy-actually.md"};function d(m,e,h,f,u,_){const p=l("ArticleMeta");return i(),s("div",null,[e[0]||(e[0]=a("h1",{id:"其实-自律很容易",tabindex:"-1"},[r("其实，自律很容易 "),a("a",{class:"header-anchor",href:"#其实-自律很容易","aria-label":'Permalink to "其实，自律很容易"'},"​")],-1)),n(p),e[1]||(e[1]=o('<p>如果你必须强迫自己去做，那你就已经输了。</p><p>这就是大多数人对自律理解错误的地方。他们一听到这个词……<em>自律……</em>脑海中就会浮现出大卫·戈金斯（David Goggins）边跑边吼、艰苦训练的画面。他们以为，要想在生活中获得某种好结果，就必须逼着自己去做那些辛苦的事情。</p><p>“自律的痛苦必须超过懒惰带来的痛苦”这句话确有道理，正如挣扎往往是一个故事中值得讲述的部分，但大多数成功的人并不是讨厌整个过程。事实上，他们乐在其中。他们<em>想要</em>去做那件难事。这指向了一个巨大的洞见：</p><p><em>你早已在朝着你本该追求的那些目标自律着。</em></p><p>这就是大脑运作的方式。</p><p>&gt; 目标是由你所处的环境灌输进你大脑的</p><p>&gt; 你的目标成为你感知现实的滤镜，塑造你关注什么、又遗忘什么</p><p>&gt; 你的大脑帮助你注意到并记住能帮你实现这些目标的信息</p><p>&gt; 于是，你自然而然地朝着这些目标行动，你的身份认同也随之固化</p><h3 id="自律是身份认同的一种特征" tabindex="-1">自律是身份认同的一种特征 <a class="header-anchor" href="#自律是身份认同的一种特征" aria-label="Permalink to &quot;自律是身份认同的一种特征&quot;">​</a></h3><p>一个从内心深处认同自己是好学生的人（因为从小到大父母都一直告诉他应该追求这个目标），并不需要强迫自己每天学习12个小时。那就是他本来的样子。</p><p>一个经历过分手、厌倦了低自信状态的健身爱好者，不会为了健康饮食或每天去健身房而感到吃力。事实上，如果他<em>不</em>这样做，反而会感到痛苦。因为如果不这样做，他就没有更接近自己的目标，而由于那个目标与他的自我认同紧密交织，他会感觉自己的生存受到了威胁——而事实也确实如此。人类在物理层面和概念层面上都要求生存（基因和文化基因），当某件对我们重要的事物受到威胁时，我们就会感到威胁，无论那是我们的宠物狗，还是我们珍视的某种信念。</p><p>这里就变得有趣起来了。</p><p>一个游戏玩家不需要强迫自己盯着电脑屏幕连续操作好几个小时。一个喜欢某部电视剧的人会躺下来一口气刷完整个系列。一个拖延工作的人——因为那个目标与他本身不契合——会没完没了地刷手机，因为他<em>的目标就是不去实现那个目标。</em></p><p>这些人并不是“懒”，可以说他们其实是有自律的，只不过是朝着一个能带来即时回报的目标在自律。这不正是自律的本质吗？对一个目标持续不断的努力。而普通人对平庸生活的坚持，真是令人惊叹。是的，大多数人只是没有意识到，他们对舒适的渴望超过了他们对改变的渴望。事实上，那正是他们的目标。</p><p>“但是丹！那些事情又轻松又舒服！根本不需要费力气！”</p><p>没错，对我来说，每天写作也是舒服的。对我来说，不去健身房反而比去健身房更痛苦。我<em>试着</em>像小时候那样玩电子游戏，可我就是做不到。它们既无聊又过度刺激。我有更值得做的事。</p><p>人类行为是目的性的。是控制论式的。大脑是一台实现目标的机器。我们以身份认同为透镜来解读这个世界，而被灌输进我们大脑的那些目标，塑造了铸就我们自身的行为。</p><p>如果我们能理解这个过程，或者对其进行逆向工程，我们就能利用它去实现几乎不可能的目标。</p><p>你在读这篇文章，是因为你正试图强迫自己变得自律。但那永远行不通。无论你是想赚更多钱，还是想为考试而学习，只要你遵循这个过程，你就不必再担心分心或拖延。</p><h3 id="悬置期就是实验室" tabindex="-1">悬置期就是实验室 <a class="header-anchor" href="#悬置期就是实验室" aria-label="Permalink to &quot;悬置期就是实验室&quot;">​</a></h3><p>你<em>想要变得自律</em>的原因，是你已经耗尽了当前这个人生阶段。</p><p>你开始注意到自己已经停滞不前。</p><p>你开始注意到每一天都和前一天一样。</p><p>你开始注意到，如果你继续做同样的事情，你就不会实现你想要的生活。</p><p>你正处于悬置期，而你已经不想再待在那里了。</p><p>这很痛苦。但你误读了这种痛苦，想到的第一个解决办法就是：<em>更自律一点。</em>这正是大多数人陷入循环的地方——强迫自己去做不想做的事，两周后就放弃，回到自己曾发誓要摆脱的生活方式。</p><p>痛苦是变化正在发生的信号。</p><p>走出去的方法，是迎向它。去清醒地意识到你当前的生活有多么痛苦。因为一旦你所处之地的痛苦超过了你想去之地的痛苦，自律就不再痛苦，因为你不必再强迫自己去做。</p><p>第一步是把以下内容写下来：</p><ul><li>你厌恶自己目前生活的一切（现在我不想听什么积极思考那一套，你错了）。</li><li>如果你不改变这些事情，你的生活将会变成什么样子，具体地写出来。</li></ul><p>然后，带着它静坐一周。反复思考它。出去散散步，让你的思绪与这些想法起舞。过一段时间，如果你没有逃避这种痛苦，你就会开启人生的下一个章节。</p><p>如果这还不管用，我们还有更多可以做的事。</p><h3 id="自律不是被建立起来的-而是被发现的" tabindex="-1">自律不是被建立起来的，而是被发现的 <a class="header-anchor" href="#自律不是被建立起来的-而是被发现的" aria-label="Permalink to &quot;自律不是被建立起来的，而是被发现的&quot;">​</a></h3><p>我在健身房训练已经大约12年了。</p><p>我每天写作已经大约5年了。</p><p>我每天走一万步已经大约4年了。</p><p>对于以上这一切，我第一次尝试养成这些习惯时，都曾多次半途放弃。我记得有一次被邀请去散步，我当时觉得那是老年痴呆才干的事。我在<em>不断确认那些帮助我实现‘维持原状’这个目标的想法。</em>我不想做那些事，却觉得自己必须做。当我最终真正养成这些习惯时，情况和之前几次强迫自己去做的时候完全不同。它们并不“难”做。它们是实验与发现的副产品。</p><p>所有这些习惯融入我生活，是出于3个具体的原因：</p><ul><li>我深刻地意识到自己生活中一个令我痛苦的问题</li><li>我去寻找证据，来支持一个理想中未来版本的自己</li><li>我改变了自己的物理环境和数字环境，以固化我的新身份</li><li>我在一周中划出固定时间去做那些事，就好像我要做一辈子一样</li></ul><p>初中时，我的自信心糟糕透了。我个子极高又瘦得像根竿子。我在自己的身体里觉得非常尴尬，所以我想改变这一点。我把这种痛苦当作动力，去主动学习健身和营养方面的知识。我甚至记得自己在坐校车上学的路上读《巅峰表现的营养时机》（Nutrient Timing For Peak Performance）。我开始在自己房间里做俯卧撑，开始参加课后力量训练，我对健身房的热爱就是从那时开始积累起来的。</p><p>为了改变我的环境，每天放学回家后，我都会直接走到电脑前，在YouTube上看两三个我最喜欢的健身博主的视频。他们会给我训练计划、动作和饮食建议，让我去尝试。在我十几岁的时候，他们是我的榜样，塑造了我如今大部分的生活方式。不要忽视社交媒体的正面力量。</p><p>在整个这段时间里，我并没有随便挑一套饮食或训练方案，然后仅仅因为别人说这样做好，就强迫自己去坚持。那些对生活不满的人身上共同的模式是：他们让别人自信满满的建议，主导了他们生活的大部分内容。</p><p>我把这一切当作一个探索与实验的时期。</p><p>我在收集愿景。我在试驾未来自己的各个片段。</p><p>我读那本营养学书籍，是因为它听起来有趣。我忍不住感到好奇。它可能能解决我的问题。在阅读的过程中，我想去<em>尝试</em>一些我正在学到的新奇做法，比如像某些奥运运动员那样，在运动前吃50克简单碳水和25克蛋白质。（顺便说一句，我读大多数书都是这样的方式。我不会强迫自己去读任何书，也不会持续不断地阅读。我读的是那些我忍不住想读的书，而且我可以接受很长一段时间不读任何东西。）</p><p>当我看健身博主的视频时，我会发现新的训练动作可以尝试，而我总是很兴奋地去试。这并不困难，也不需要强迫。去尝试那些可能改变我人生的事情，是件有趣的事。随着时间推移，我学到的所有这些小知识点，渐渐融合成了对健身和营养的深刻理解。</p><p>我成了自己的老师，也成了自己的教练。</p><p>这里的问题在于：（1）大多数人并没有高度意识到自己生活中一个令人痛苦的问题，所以他们的大脑在看到潜在解决方案时不会释放多巴胺；（2）他们学习时不去实验，所以他们永远无法取得那种能形成反馈循环、持续激励自己的进展。</p><h3 id="如何塑造一种身份认同" tabindex="-1">如何塑造一种身份认同 <a class="header-anchor" href="#如何塑造一种身份认同" aria-label="Permalink to &quot;如何塑造一种身份认同&quot;">​</a></h3><p><strong>第一步是认知。</strong> 你是谁，决定了你认为什么重要。你必须首先认识到，无论你是否意识到，你都在追逐一系列目标。这些目标框定了你解读现实的方式，你通常只会注意到那些能确认你当前生活方式的事物。</p><p>你大脑所依据运行的那些目标，源自条件反射式的灌输，而这种灌输又源自你所处的环境。你的父母、老师和所处的文化，已经把你带上了一条通往死胡同的道路。</p><p><strong>第二步是策略性的不协调感。</strong> 为了避免陷入迷失方向的状态——也就是悬置期——你要让“你现在是谁”与“你想成为谁”之间的差距不断拉大。你通过意识到，如果不改变，自己最终会走向何处，来培养对当前生活方式的不满。</p><p>通过意识到自己生活中的问题，你为大脑的模式识别做好了准备。你的大脑开始确认改变才是正确的事，并帮助你注意到能助你实现改变的信息。</p><p><strong>第三步是环境工程。</strong> 取消关注那些不能提供帮助你实现更好生活的信息的人。扔掉那些你允许自己在凌晨三点吃的食物。拿出一张纸，把你这一周要做的事情精确到每小时地规划出来。每周复盘并迭代。你需要那个反馈循环。</p><p>让自己沉浸在那些能为你提供<em>可尝试之物</em>的人、地方和事物之中。即使你不同意某些账号的观点，也去关注他们。在亚马逊上一直刷，直到找到一本听起来有趣的书，即便你最终只读了前几页也没关系。意图才是关键。意图就是你为大脑指明一个方向，让它朝那个方向重新构建自己。</p><p><strong>第四步是自我实验。</strong> 因为不通过实验解决的问题，永远不会被真正彻底地解决。与被指派另一个目标不同，你要尝试一切，直到找到那一件让你无法自拔、离不开的事情。然后，你不断重复这个过程，直到它成为你本来的样子。</p><p>感谢阅读。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/self-discipline-is-easy-actually">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',61))])}const b=t(c,[["render",d]]);export{y as __pageData,b as default};
